int reverse(int n, int rev = 0) {
    if (n == 0) return rev;
    return reverse(n / 10, rev * 10 + n % 10);
}
int main() {
    std::cout << reverse(123);
    return 0;
}

int digitSum(int n) {
    if (n == 0) return 0;
    return (n % 10) + digitSum(n / 10);
}
int main() {
    std::cout << digitSum(123);
    return 0;
}

